        per_game_so_far: r1(pg, 1), per_game_needed_rest_of_way: need <= 0 ? 0 : r1(needPg, 1), already_there: need <= 0,
        projected_final_at_current_pace: Math.round(so + pg * left),
        ...(need > 0 && needPg ? { cushion: `${pg >= needPg ? "ahead" : "behind"}: his ${r1(pg, 1)} a game vs ${r1(needPg, 1)} needed (${Math.round(100 * (pg / needPg - 1))}%)`,
          games_he_can_miss_at_current_pace: pg > 0 ? Math.max(0, left - Math.ceil(need / pg)) : 0 } : {}),
