      const OPP = { rush_yds: "opp_rush_yds", rush_td: "opp_rush_yds", pass_yds: "opp_pass_yds", pass_td: "opp_pass_yds", rec: "opp_pass_yds", rec_yds: "opp_pass_yds", rec_td: "opp_pass_yds", def_sacks: "sacked" };
      const col = OPP[k], Rt = ((await base())[lg]?.teams || []).find((t) => t.team === out.team);
      if (col && D.ti[col] != null && Rt?.games) {
        const per = {};
        for (const r of D.trows) { const o = (per[r[0]] ||= { g: 0, v: 0 }); o.g++; o.v += r[D.ti[col]] || 0; }
        const pg2 = Object.fromEntries(Object.entries(per).map(([t, o]) => [t, o.v / o.g])), order = Object.values(pg2).sort((x, y) => y - x);
        const key = (name) => Object.keys(D.teams).find((t) => D.teams[t][0] === name), avg = (xs) => (xs.length ? r1(xs.reduce((t, x) => t + x, 0) / xs.length, 1) : null);
        const row = (gm) => { const t = key(gm.opp), v = t != null ? pg2[t] : null; return { wk: gm.wk, opp: gm.opp, home: gm.loc === "H", allows_per_game: r1(v, 1), rank: v == null ? null : `${1 + order.filter((x) => x > v).length} of ${order.length} (1 = gives up the most)` }; };
        const rest = Rt.games.filter((gm) => !gm.res).map(row), faced = Rt.games.filter((gm) => gm.res).map(row);
        const what = col === "sacked" ? "sacks their offense gives up per game" : col === "opp_rush_yds" ? "rush yards their defense allows per game" : "pass yards their defense allows per game";
        out.schedule_left = { what, league_average: avg(Object.values(pg2)), remaining_opponents_average: avg(rest.map((x) => x.allows_per_game).filter((x) => x != null)),
          faced_so_far_average: avg(faced.map((x) => x.allows_per_game).filter((x) => x != null)), games: rest,
          note: "Softer than the defenses he's faced = his pace has room to hold; tougher = expect it to dip. Cite the toughest and softest games left by name." };
      }
